package com.dormrepair.v2.images;
import java.util.*;
import java.nio.file.*;
import java.io.*;
import java.awt.image.BufferedImage;
import javax.imageio.*;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import com.dormrepair.v2.identity.*;
@Service @ConditionalOnProperty(name="app.v2.enabled",havingValue="true")
public class PrivateImageService {
 private final JdbcTemplate jdbc;private final RbacIdentity identity;private final SecurityAudit audit;private final Path root;
 public PrivateImageService(JdbcTemplate j,RbacIdentity i,SecurityAudit a,@Value("${app.v2.images.directory:${java.io.tmpdir}/dorm-repair-v2-private-images}") String directory)throws IOException{jdbc=j;identity=i;audit=a;String database=jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<String>)c->{com.dormrepair.v2.platform.migration.V2DatabaseTarget.verify(c);return c.getCatalog();});root=Path.of(directory).toAbsolutePath().normalize().resolve(database);String s=root.toString().replace('\\','/').toLowerCase(Locale.ROOT);if(s.contains("/static/")||s.contains("/public/")||s.contains("src/main/resources")||s.contains("/meta-inf/resources/")||s.contains("/target/classes/")||s.contains("/target/test-classes/"))throw new IllegalStateException("Private image directory cannot be web resources");Files.createDirectories(root);if(Files.isSymbolicLink(root)||!root.toRealPath().equals(root))throw new IllegalStateException("Image root must not use symbolic links");}
 static ResponseStatusException error(int s){return new ResponseStatusException(HttpStatus.valueOf(s));}
 void lock(){jdbc.queryForObject("select guard_key from public.system_guard where guard_key='rbac-admin' for update",String.class);}
 Path path(String key){if(!key.matches("[a-f0-9]{32}\\.(jpg|png)"))throw new IllegalStateException("Invalid storage key");Path p=root.resolve(key).normalize();if(!p.startsWith(root)||Files.isSymbolicLink(p))throw error(404);return p;}
 void remove(Path p){try{Files.deleteIfExists(p);}catch(IOException e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Private image removal deferred to explicit cleanup");}}
 Map<String,Object> own(long id,long owner){var rows=jdbc.queryForList("select * from public.private_image where id=? and owner_id=? and state<>'CANCELED'",id,owner);if(rows.isEmpty())throw error(404);return rows.getFirst();}
 Map<String,Object> view(Map<String,Object> r){return Map.of("id",r.get("id").toString(),"contentType",r.get("content_type"),"width",r.get("width"),"height",r.get("height"),"bytes",r.get("byte_size"),"state",r.get("state"),"contentUrl","/api/v2/images/"+r.get("id")+"/content");}
 @Transactional public Object upload(MultipartFile file)throws IOException{lock();long owner=identity.require("draft:own").user().id();if(file==null||file.isEmpty()||file.getSize()>5242880)throw error(400);byte[] raw=file.getBytes();String format;if(raw.length>=3&&(raw[0]&255)==255&&(raw[1]&255)==216&&(raw[2]&255)==255)format="JPEG";else if(raw.length>=8&&Arrays.equals(Arrays.copyOf(raw,8),new byte[]{(byte)137,80,78,71,13,10,26,10}))format="PNG";else if(raw.length>=12&&new String(raw,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")&&new String(raw,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WEBP"))format="WEBP";else throw error(400);
 BufferedImage decoded;try(var input=ImageIO.createImageInputStream(new ByteArrayInputStream(raw))){var readers=ImageIO.getImageReaders(input);if(!readers.hasNext())throw error(400);var reader=readers.next();try{reader.setInput(input,true,true);if(!reader.getFormatName().equalsIgnoreCase(format)&&!(format.equals("JPEG")&&reader.getFormatName().equalsIgnoreCase("JPG")))throw error(400);int w=reader.getWidth(0),h=reader.getHeight(0);if(w<1||h<1||w>6000||h>6000||(long)w*h>20000000)throw error(400);decoded=reader.read(0);if(decoded==null)throw error(400);}finally{reader.dispose();}}catch(ResponseStatusException e){throw e;}catch(Exception e){throw error(400);}
 boolean alpha=decoded.getColorModel().hasAlpha();String output=alpha?"png":"jpg";var pixels=new BufferedImage(decoded.getWidth(),decoded.getHeight(),alpha?BufferedImage.TYPE_INT_ARGB:BufferedImage.TYPE_INT_RGB);var graphics=pixels.createGraphics();try{graphics.drawImage(decoded,0,0,null);}finally{graphics.dispose();}var encoded=new ByteArrayOutputStream();if(!ImageIO.write(pixels,output,encoded))throw error(400);byte[] clean=encoded.toByteArray();if(clean.length>5242880)throw error(400);String key=UUID.randomUUID().toString().replace("-","")+"."+output;Path destination=path(key);try{Files.write(destination,clean,StandardOpenOption.CREATE_NEW);}catch(FileAlreadyExistsException e){throw e;}catch(IOException e){remove(destination);throw e;}TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCompletion(int status){if(status==STATUS_ROLLED_BACK)remove(destination);}});String sha;try{sha=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(clean));}catch(Exception e){throw new IllegalStateException(e);}long id=jdbc.queryForObject("insert into public.private_image(owner_id,storage_key,content_type,width,height,byte_size,sha256) values (?,?,?,?,?,?,?) returning id",Long.class,owner,key,alpha?"image/png":"image/jpeg",pixels.getWidth(),pixels.getHeight(),clean.length,sha);audit.record(owner,"IMAGE_UPLOADED","PRIVATE_IMAGE",id,Map.of("bytes",clean.length));return view(own(id,owner));}
 @Transactional(readOnly=true) public Object metadata(long id){return view(own(id,identity.require("draft:own").user().id()));}
 public record Content(byte[] bytes,String contentType){}
 @Transactional(readOnly=true) public Content content(long id)throws IOException{var row=own(id,identity.require("draft:own").user().id());Path p=path((String)row.get("storage_key"));if(!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS))throw error(404);return new Content(Files.readAllBytes(p),(String)row.get("content_type"));}
 @Transactional public Object cancel(long id){lock();long owner=identity.require("draft:own").user().id();var row=own(id,owner);if(!"STAGED".equals(row.get("state")))throw error(409);jdbc.update("update public.private_image set state='CANCELED' where id=?",id);Path p=path((String)row.get("storage_key"));TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){remove(p);}});audit.record(owner,"IMAGE_CANCELED","PRIVATE_IMAGE",id,Map.of());return Map.of("id",Long.toString(id),"state","CANCELED");}
 public void bind(long draft,int number,long owner,Object requested){long revision=jdbc.queryForObject("select id from public.repair_draft_revision where draft_id=? and revision_no=?",Long.class,draft,number);List<Long> ids;if(requested==null)ids=jdbc.queryForList("select i.image_id from public.draft_revision_image i join public.repair_draft_revision r on r.id=i.revision_id where r.draft_id=? and r.revision_no=? order by i.position",Long.class,draft,number-1);else{if(!(requested instanceof List<?> list)||list.size()>6)throw error(400);ids=new ArrayList<>();for(Object value:list){if(!(value instanceof String s))throw error(400);ids.add(com.dormrepair.v2.platform.api.V2Id.parse(s).value());}if(new HashSet<>(ids).size()!=ids.size())throw error(400);}int position=0;for(long id:ids){var row=own(id,owner);if(row.get("bound_draft_id")!=null&&((Number)row.get("bound_draft_id")).longValue()!=draft)throw error(409);jdbc.update("update public.private_image set state='BOUND',bound_draft_id=? where id=?",draft,id);jdbc.update("insert into public.draft_revision_image values (?,?,?)",revision,id,position++);}}
 @Transactional(readOnly=true) public Object revisionImages(long draft,int number){long owner=identity.require("draft:own").user().id();if(jdbc.queryForObject("select count(*) from public.repair_draft d join public.repair_draft_revision r on r.draft_id=d.id where d.id=? and d.owner_id=? and r.revision_no=?",Integer.class,draft,owner,number)!=1)throw error(404);return jdbc.queryForList("select i.* from public.private_image i join public.draft_revision_image b on b.image_id=i.id join public.repair_draft_revision r on r.id=b.revision_id where r.draft_id=? and r.revision_no=? order by b.position",draft,number).stream().map(this::view).toList();}
 @Transactional public Object cleanup(){lock();long actor=identity.require("role:manage").user().id();identity.require("user:manage");int expired=jdbc.update("update public.private_image set state='CANCELED' where state='STAGED' and created_at<current_timestamp-interval '24 hours'");int removed=0;try(var files=Files.list(root)){for(Path file:files.toList()){String key=file.getFileName().toString();if(!key.matches("[a-f0-9]{32}\\.(jpg|png)"))continue;var rows=jdbc.queryForList("select state from public.private_image where storage_key=?",String.class,key);if(rows.equals(List.of("CANCELED"))||(rows.isEmpty()&&Files.getLastModifiedTime(file).toMillis()<System.currentTimeMillis()-86400000L)){Path target=path(key);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){remove(target);}});removed++;}}}catch(IOException e){throw new IllegalStateException("Private cleanup failed");}audit.record(actor,"IMAGE_CLEANUP","PRIVATE_IMAGE",null,Map.of("expired",expired,"files",removed));return Map.of("expired",expired,"scheduledDeletes",removed);}

 @Transactional(readOnly=true) public Content orderContent(long order,long image)throws IOException{
  var a=identity.actor();var rows=jdbc.queryForList("select i.*,o.student_id,o.repairer_id from public.v2_order v join public.repair_order o on o.id=v.order_id join public.draft_revision_image b on b.revision_id=v.revision_id join public.private_image i on i.id=b.image_id where v.order_id=? and i.id=? and i.state='BOUND'",order,image);if(rows.isEmpty())throw error(404);var r=rows.getFirst();boolean allowed=a.permissions().contains("legacy:admin")||(a.permissions().contains("draft:own")&&((Number)r.get("student_id")).longValue()==a.user().id())||(a.permissions().contains("legacy:repairer")&&r.get("repairer_id")!=null&&((Number)r.get("repairer_id")).longValue()==a.user().id());if(!allowed)throw error(404);Path p=path((String)r.get("storage_key"));if(!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS))throw error(404);return new Content(Files.readAllBytes(p),(String)r.get("content_type"));
 }
}